"const fs = require('fs');

const pgeTalents = JSON.parse(fs.readFileSync('imported_pge_talents.json', 'utf8'));

// 1. Update Code.gs to add importPGETalents() function
let codeGs = fs.readFileSync('Code.gs', 'utf8');

const pgeImportFunction = `
/**
 * Auto-imports the 32 PGE Freelance Content Creator candidates
 */
function importPGETalents() {
  const talents = ${JSON.stringify(pgeTalents, null, 2)};
  return importTalentsBulk(talents);
}
`;

if (!codeGs.includes('function importPGETalents()')) {
  codeGs += '\n' + pgeImportFunction;
  fs.writeFileSync('Code.gs', codeGs);
  console.log('Added importPGETalents() to Code.gs');
}

// 2. Update preview.html so local preview opens with all 32 candidates loaded!
let previewHtml = fs.readFileSync('preview.html', 'utf8');
previewHtml = previewHtml.replace(
  /function getFallbackMockData\(\) \{[\s\S]*?\}/,
  `function getFallbackMockData() {\n      return ${JSON.stringify(pgeTalents, null, 6)};\n    }`
);
fs.writeFileSync('preview.html', previewHtml);
console.log('Updated preview.html with 32 PGE candidates');

// 3. Update Index.html fallback
let indexHtml = fs.readFileSync('Index.html', 'utf8');
indexHtml = indexHtml.replace(
  /function getFallbackMockData\(\) \{[\s\S]*?\}/,
  `function getFallbackMockData() {\n      return ${JSON.stringify(pgeTalents, null, 6)};\n    }`
);
fs.writeFileSync('Index.html', indexHtml);
console.log('Updated Index.html with 32 PGE candidates');
"
